import { Icon } from "@/registry/erbium/ui/icon";

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupTextarea,
} from "@/registry/erbium/ui/input-group";
import { Spinner } from "@/registry/erbium/ui/spinner";

const SpinnerInputGroup = () => (
  <div className="flex w-full max-w-md flex-col gap-group">
    <InputGroup>
      <InputGroupInput placeholder="Send a message..." disabled />
      <InputGroupAddon align="inline-end">
        <Spinner />
      </InputGroupAddon>
    </InputGroup>
    <InputGroup>
      <InputGroupTextarea placeholder="Send a message..." disabled />
      <InputGroupAddon align="block-end">
        <Spinner /> Validating...
        <InputGroupButton className="ml-auto" variant="default">
          <Icon name="arrow-up-01" />
          <span className="sr-only">Send</span>
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  </div>
);

export default SpinnerInputGroup;

import ExampleSpinnerInputGroup from "../examples/spinner-input-group";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleSpinnerInputGroup />
  </div>
);

export default Example;
